"use client";
import { useState } from "react";
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { currency, getCashFlow, ranges, type TimeRange } from "@/lib/mock-data";
export default function CashFlowChart() {
 const [range, setRange] = useState<TimeRange>("1M");
 return <section className="panel chart-panel" aria-labelledby="cashflow-title"><div className="panel-heading"><div><h2 id="cashflow-title">Cash flow</h2></div><span className="sample-tag">Sample data</span></div><div className="chart-toolbar"><div className="legend"><span><i className="income-dot" />Income</span><span><i className="spending-dot" />Spending</span></div><div className="range-filters" aria-label="Chart time range">{ranges.map(item => <button key={item} aria-pressed={range === item} className={range === item ? "active" : ""} onClick={() => setRange(item)}>{item}</button>)}</div></div><div className="chart" role="img" aria-label={`Income in red and spending in green for ${range}. Hover to inspect dollar amounts.`}><ResponsiveContainer width="100%" height="100%"><LineChart data={getCashFlow(range)} margin={{ top: 20, right: 12, left: -20, bottom: 10 }}><CartesianGrid stroke="#eeeeee" vertical={false} strokeDasharray="3 5" /><XAxis dataKey="date" axisLine={false} tickLine={false} minTickGap={40} tick={{ fill: "#737373", fontSize: 11 }} tickMargin={14} tickFormatter={value => new Date(`${String(value)}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" })} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#737373", fontSize: 11 }} tickFormatter={value => `$${Number(value) / 1000}k`} /><Tooltip labelFormatter={value => new Date(`${String(value)}T12:00:00`).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })} formatter={value => currency(Number(value))} contentStyle={{ border: "1px solid #e8e8e8", borderRadius: 10, fontSize: 12 }} /><Line name="Income" type="monotone" dataKey="income" stroke="#E5484D" strokeWidth={2.5} dot={false} activeDot={{ r: 5, stroke: "#fff", strokeWidth: 3 }} animationDuration={550} /><Line name="Spending" type="monotone" dataKey="spending" stroke="#22C55E" strokeWidth={2.5} dot={false} activeDot={{ r: 5, stroke: "#fff", strokeWidth: 3 }} animationDuration={550} /></LineChart></ResponsiveContainer></div><div className="chart-footer"><span>USD</span></div></section>;
}

